	private static SlotPlan singleSummaryRow(int keySlot, long key, int summarySlot, NativeResultCell summary) {
		return new SlotPlan() {
			@Override
			public RowCursor open(RowState row) {
				return new RowCursor() {
					private int index;
					private int mark = -1;

					@Override
					public boolean next() {
						if (mark >= 0) {
							row.rollback(mark);
							mark = -1;
						}
						if (index++ > 0) {
							return false;
						}
						mark = row.mark();
						assertThat(row.bind(keySlot, key)).isTrue();
						assertThat(row.bindSummary(summarySlot, summary)).isTrue();
						return true;
					}

					@Override
					public void close() {
						if (mark >= 0) {
							row.rollback(mark);
							mark = -1;
						}
					}
				};
			}

			@Override
			public long producedMask() {
				return (1L << keySlot) | (1L << summarySlot);
			}
		};
	}

	private static SlotPlan track(SlotPlan delegate, Counts counts, Runnable afterFirst) {
		return new SlotPlan() {
			@Override
			public RowCursor open(RowState row) throws IOException {
				counts.opens.incrementAndGet();
				RowCursor cursor = delegate.open(row);
				return new RowCursor() {
					private boolean firstNotified;
					private boolean closed;

					@Override
					public boolean next() throws IOException {
						counts.advances.incrementAndGet();
						boolean result = cursor.next();
						if (result && !firstNotified) {
							firstNotified = true;
							if (afterFirst != null) {
								afterFirst.run();
							}
						}
						return result;
					}

					@Override
					public void close() {
						if (!closed) {
							closed = true;
							counts.closes.incrementAndGet();
							cursor.close();
						}
					}
				};
			}

			@Override
			public long producedMask() {
				return delegate.producedMask();
			}
		};
	}

	private static boolean hasReplaySpill(Path path) throws IOException {
		return RecordingFile.readAllEvents(path)
				.stream()
				.anyMatch(event -> event.getEventType().getName().equals("org.eclipse.rdf4j.lmdb.NativeExecutionPhase")
						&& event.getString("phase").equals("spill")
						&& event.getStackTrace() != null
						&& event.getStackTrace()
								.getFrames()
								.stream()
								.anyMatch(frame -> frame.getMethod()
										.getType()
										.getName()
										.equals(NativeResultReplay.class.getName())));
	}

	private static void restoreProperty(String property, String previous) {
		if (previous == null) {
			System.clearProperty(property);
		} else {
			System.setProperty(property, previous);
		}
	}

	private static void assertOwnedCancellation(Throwable failure, NativeCancellationToken token) {
		assertThat(failure).isInstanceOf(KernelQueryCancelledException.class);
		KernelQueryCancelledException signal = (KernelQueryCancelledException) failure;
		assertThat(signal.origin()).as("query cancellation must retain its exact token origin").isSameAs(token);
		assertThat(signal.observedBy(token)).isTrue();
	}

	private static final class Counts {
		final AtomicInteger opens = new AtomicInteger();
		final AtomicInteger advances = new AtomicInteger();
		final AtomicInteger closes = new AtomicInteger();
	}

	private record Output(long key, long right, long left) {
	}

